(function () {
  // The published body is the partial UpdateTaskRequest (workspaces-service
  // handler/tasks.go:305-311), NOT the task. It carries `status` only when the
  // write changed it, and a title-only or assignment write carries no `status`
  // key at all. That is the NORMAL case and it must resolve successfully, not
  // error: every task write in the account reaches this node.
  var t = (d && typeof d === 'object' && !Array.isArray(d)) ? d : {};
  var id = (typeof t.id === 'string') ? t.id : '';
  var has = Object.prototype.hasOwnProperty.call(t, 'status');
  var s = (typeof t.status === 'string') ? t.status : '';

  // A CLOSED allow-list with an explicit no-match branch. Never a fail-open
  // else: an undefined status is accepted everywhere except the board, and it
  // does fire this trigger (traps register, phase 0).
  var DECIDES = { approved: 1, declined: 1 };
  var ok = id !== '' && has && Object.prototype.hasOwnProperty.call(DECIDES, s);

  var reason;
  if (id === '') reason = 'ignored:delta-has-no-task-id';
  else if (!has) reason = 'ignored:delta-carries-no-status-key';
  else if (s === '') reason = 'ignored:status-key-is-not-a-string';
  else if (!ok) reason = 'ignored:status-not-a-decision:' + s;
  else reason = 'proceed:status-delta-is-a-decision:' + s;

  return {
    proceed: ok,
    task_id: id,
    delta_status: s,
    delta_keys: Object.keys(t).sort().join(','),
    reason: reason
  };
})()

(function () {
  // The task read back in full. The delta could not carry the record reference
  // (UpdateTaskRequest has no metadata field, model/api.go:600-627); the
  // aggregate can, which is why the task-get exists at all.
  var t = (task && typeof task === 'object' && !Array.isArray(task)) ? task : {};
  var tags = Array.isArray(t.tags) ? t.tags : [];
  var meta = (t.metadata && typeof t.metadata === 'object') ? t.metadata : {};
  var status = (typeof t.status === 'string') ? t.status : '';

  // Re-read, never the delta: the delta may be stale by the time the get
  // returns, and only the aggregate carries space_id, tags and the handle.
  var inSpace = t.space_id === space;
  var isReferral = tags.indexOf('referral') >= 0;
  var DECIDES = { approved: 'ACCEPT', declined: 'DECLINE' };
  var isDecision = Object.prototype.hasOwnProperty.call(DECIDES, status);

  // Contract artefact 4: `source` is the decision handle and `folder` is the
  // brokerage, so a referral task groups per brokerage on the board AND stays
  // resolvable to its decision. metadata.decision_id is the belt-and-braces
  // copy; `folder` is read ONLY as the pre-migration fallback, and which one
  // answered is recorded so a run log says so.
  var handle = '', via = '';
  if (typeof t.source === 'string' && t.source !== '') { handle = t.source; via = 'source'; }
  else if (typeof meta.decision_id === 'string' && meta.decision_id !== '') { handle = meta.decision_id; via = 'metadata.decision_id'; }
  else if (typeof t.folder === 'string' && t.folder !== '') { handle = t.folder; via = 'folder(legacy)'; }
  else { via = 'none'; }

  var ok = inSpace && isReferral && isDecision && handle !== '';
  var reason;
  if (!inSpace) reason = 'ignored:not-in-space:' + (t.space_id || '');
  else if (!isReferral) reason = 'ignored:not-tagged-referral:' + tags.join('|');
  else if (!isDecision) reason = 'ignored:task-status-is-not-a-decision:' + status;
  else if (handle === '') reason = 'ignored:no-decision-handle-on-task';
  else reason = 'proceed:' + status + ':decision=' + handle + ':via=' + via;

  return {
    proceed: ok,
    task_id: t.id || '',
    task_status: status,
    decision_id: handle,
    handle_via: via,
    outcome: DECIDES[status] || '',
    decision_status: status === 'approved' ? 'ISSUED' : (status === 'declined' ? 'DECLINED' : ''),
    title: t.title || '',
    reason: reason
  };
})()

(function () {
  // The one place a filter STRING is built. It cannot be assembled by pipe
  // concatenation inside an http node's query value: the flows MCP JSON.parses
  // any value that looks like JSON, so a filter written as a literal
  // {"conditions":[...]} would reach the wire as a Go map rendering, not JSON.
  var r = (rec && typeof rec === 'object') ? rec : {};
  var d = (r.data && typeof r.data === 'object') ? r.data : {};
  var brokerKey = d.distributor_account_id || '';
  return {
    decision_id: r.id || '',
    submission_id: d.submission_id || '',
    broker_key: brokerKey,
    // broker_config's only joinable indexed keyword is broker_id (artefact 2).
    // A sentinel that matches nothing keeps the read bounded when the decision
    // names no distributor, rather than widening to every broker.
    broker_filter: JSON.stringify({
      conditions: [{ field: 'broker_id', keyword: brokerKey || '__no_broker_key__' }]
    })
  };
})()

(function () {
  var g = gate || {};
  var d = (dec && typeof dec === 'object') ? dec : {};
  var s = (sub && typeof sub === 'object') ? sub : {};
  var brokerRows = (brokers && brokers.results) ? brokers.results : [];
  var broker = (brokerRows.length && brokerRows[0].data) ? brokerRows[0].data : {};

  var outcome = g.outcome;                 // ACCEPT | DECLINE
  var newStatus = g.decision_status;       // ISSUED | DECLINED
  var isAccept = outcome === 'ACCEPT';

  // Idempotency and self-loop safety. The gate is the decision record's own
  // decision_status, written FIRST (plan 5.3 rule 3) so a replay of the same
  // move is a no-op. A genuine underwriter reversal (ISSUED -> DECLINED) is
  // still allowed: only the identical terminal status is refused.
  var already = (typeof d.decision_status === 'string') ? d.decision_status : '';
  var replay = already === newStatus;

  var ref = s.quote_reference || d.quote_id || g.decision_id;
  var name = s.gen_policyholder_name || '';

  // The quotation schedule's broker-facing narrative has to match the NEW
  // outcome. Left alone it still reads "referred for underwriter review" on a
  // quote that has just been issued. underwriter_reasons is never crossed over
  // to the broker (artefact 3 assertion A16).
  var brokerReasons;
  if (isAccept) {
    brokerReasons = ['Your quotation has been approved by an underwriter and is attached.'];
  } else if (Array.isArray(d.decline_reasons) && d.decline_reasons.length) {
    brokerReasons = d.decline_reasons.slice(0);
  } else {
    brokerReasons = ['Your application has been declined following underwriter review.'];
  }

  var docName = (isAccept ? 'quotation-schedule-' : 'decline-notice-') + ref;
  var docFolder = 'antipodean.quotes';
  var docBucket = 'microstrate-documents';
  var docKey = docFolder + '.' + docName + '.pdf';

  var to = broker.primary_contact_email || fallbackTo;
  var toName = broker.primary_contact_name || broker.brokerage_name || 'Broker';

  var subject = isAccept
    ? ('Quote issued - ' + ref + ' - ' + name)
    : ('Quote declined - ' + ref + ' - ' + name);

  var reasonsHtml = '';
  for (var i = 0; i < brokerReasons.length; i++) {
    reasonsHtml += '<li>' + String(brokerReasons[i]) + '</li>';
  }
  var body =
    '<p>Dear ' + toName + ',</p>' +
    '<p>The referral on quote <strong>' + ref + '</strong> for <strong>' + name +
    '</strong> has been reviewed by an underwriter and the outcome is <strong>' +
    (isAccept ? 'ISSUED' : 'DECLINED') + '</strong>.</p>' +
    '<ul>' + reasonsHtml + '</ul>' +
    (isAccept
      ? ('<p>Quotation valid until: ' + (d.quote_validity_expiry || 'see schedule') +
         '.<br>Total payable: ' + (d.total_payable === undefined ? '' : d.total_payable) + '.</p>' +
         '<p>The quotation schedule has been generated and filed as <code>' + docKey + '</code>.</p>')
      : ('<p>A decline notice has been generated and filed as <code>' + docKey + '</code>.</p>')) +
    '<p>Decision reference: ' + g.decision_id + ' (task ' + g.task_id + ').</p>' +
    '<p>Antipodean Underwriting</p>';

  return {
    proceed: !replay,
    replay: replay,
    skip_reason: replay ? ('skip:decision-already-' + already) : '',
    decision_id: g.decision_id,
    task_id: g.task_id,
    outcome: outcome,
    decision_status: newStatus,
    previous_decision_status: already,
    decided_at: new Date().toISOString(),
    // No underwriter identity is recoverable: the task delta carries no actor
    // and model.Task has CreatedBy but no UpdatedBy. The task is named instead
    // of inventing a person.
    decided_by: 'underwriter-via-task:' + g.task_id,
    broker_reasons: brokerReasons,
    quote_reference: ref,
    policyholder: name,
    doc_name: docName,
    doc_folder: docFolder,
    doc_key: docKey,
    // decision_config.issued_document_refs items are OBJECTS
    // {document_type, object_key, template_id} — a bare string 400s the write.
    doc_refs: [{
      document_type: isAccept ? 'quotation_schedule' : 'decline_notice',
      object_key: 'obj://' + docBucket + '/' + docKey,
      template_id: docTemplate
    }],
    doc_payload: {
      quote_reference: ref,
      gen_policyholder_name: name,
      gen_occupation: s.gen_occupation || '',
      quote_validity_expiry: d.quote_validity_expiry || '',
      outcome_status: outcome,
      total_payable: d.total_payable === undefined ? 0 : d.total_payable,
      broker_reasons: brokerReasons
    },
    email_to: to,
    email_to_name: toName,
    email_resolved_from: broker.primary_contact_email ? 'broker_config' : 'static.fallback_broker_email',
    email_subject: subject,
    email_body_html: body,
    idempotency_key: 'referral-decide-' + g.decision_id + '-' + newStatus,
    comment_body: 'flow 11 referral-decide: decision ' + g.decision_id + ' set to ' +
      newStatus + ' (' + outcome + '). Document ' + docKey + '. Notified ' + to + '.'
  };
})()
